// H6b: trusted same-Worker bridge. The sink runs inside the channel
// count/audience/deletion transaction, so a failure rolls both sides back.
if (ingress) ingress.setInvalidationSink(signal => {
  conversations!.bridgeChannelInvalidation({
    channelRef: signal.conversationRef, reasonRef: channelBridgeReason(signal), sourceWatermark: signal.watermark,
  });
});

